In the following discussion, we derive optimal designs for the three
families of correlation functions, which are given by
\eqref{eq:rho=L/ta}, \eqref{eq:cauchy_fam} and \eqref{eq:mittag-leffler_fam}.
The function $Q(t)=\sum_{j=1}^\infty\rho(j t)$\vspace*{2pt}
plays an important role in the asymptotic analysis by Bickel and Herzberg (\citeyear{BickelHerzberg1979}),
but in the case of long-range dependence, this function is infinite.
For an asymptotic analysis under long-range dependence, we
introduce the function


\begin{eqnarray}
\label{qalph}
Q_\alpha(t)=\lim_{N\to\infty}\frac{1}{d_\alpha(N)}\sum_{j=1}^N\rho_\alpha(j t),
\end{eqnarray}

where the normalizing sequence is given by

\begin{eqnarray*}
d_\alpha(N)=

\cases{
N^{1-\alpha},
&\quad\mbox{if }$\alpha<1$\mbox{ and }$\rho_\alpha$\mbox{ has the form }\eqref{eq:cauchy_fam}\mbox{ or }\eqref{eq:mittag-leffler_fam},
\cr
\ln N, &\quad\mbox{if }$\alpha=1$\mbox{ and }$\rho_\alpha$\mbox{ has the form }\eqref{eq:cauchy_fam}\mbox{ or }\eqref{eq:mittag-leffler_fam},
\cr
L(N) N^{1-\alpha}, &\quad\mbox{if }$\alpha<1$\mbox{ and }$\rho_\alpha$\mbox{ has the form }\eqref{eq:rho=L/ta},
\cr
L(N) \ln N, &\quad\mbox{if }$\alpha=1$\mbox{ and }$\rho_\alpha$\mbox{ has the form }\eqref{eq:rho=L/ta},
}

\end{eqnarray*}

and show in Lemma~\ref{lemma1} below that the function $Q_\alpha(t)$ is well
defined.






































\begin{lemma}\label{lemma1}
If the correlation function $\rho_\alpha(t)$ belongs to the Cauchy,
SVF family or to the Mittag-Leffler family with
$0< \alpha\leq1, 0 < \nu\leq1, \nu\leq\beta, (\nu,\beta) \neq
(1,1)$, then the limit in~(\ref{qalph}) exists and is given by

\begin{eqnarray*}
Q_\alpha(t)=

\cases{
\displaystyle\frac{c}{(1-\alpha)|t|^\alpha},&\quad $0<\alpha<1$,\cr
\displaystyle\frac{c}{|t|},&\quad$\alpha=1$,
}

\end{eqnarray*}

where

\begin{eqnarray*}
c=

\cases{
\displaystyle\frac{\Gamma(\beta)}{\Gamma(\beta-\nu)},
&\quad\mbox{\textup{if} } $\rho_\alpha(t)$\mbox{ \textup{belongs to the Mittag-Leffler family}},
\cr
1,&\quad\mbox{\textup{otherwise}}.
}

\end{eqnarray*}
\end{lemma}

\begin{pf}
Define the function

\begin{eqnarray*}
Q_{\alpha,N}(t)=\frac{1}{d_\alpha(N)} \sum_{j=1}^N\rho_\alpha(j t)
\end{eqnarray*}

and assume that the correlation function $\rho_\alpha(t)$
is an element of the Cauchy family.
Since the function $\rho_\alpha(t)$ defined in \eqref{eq:cauchy_fam}
is positive and decreasing for $0<\alpha<1$, we have

\begin{eqnarray*}
Q_{\alpha,N}(t)&=&\frac{1}{N^{1-\alpha}}\int_0^N
\frac{1}{(1+|st|^\beta)^{\alpha/\beta}}\, \mathrm{d}s +\mathrm{O}\biggl(\frac{1}{N^{1-\alpha}}\biggr)
\\
&=&\frac{1}{N^{1-\alpha}}N\int_0^N\frac{\mathrm{d}(s/N)}{N^\alpha(1/N^\beta+|st/N|^\beta)^{\alpha/\beta}}
+\mathrm{O}\biggl(\frac{1}{N^{1-\alpha}}\biggr)
\\
&=&\int_0^1\frac{\mathrm{d}v}{(|vt|^\beta)^{\alpha/\beta}}+\mathrm{O}\biggl(\frac{1}{N^{\alpha-\alpha^2}}\biggr)
=
\frac{1}{(1-\alpha)|t|^\alpha}+\mathrm{O}\biggl(\frac{1}{N^{\alpha-\alpha^2}}\biggr)
\\
&=& Q_\alpha(t) +\mathrm{O}\biggl(\frac{1}{N^{\alpha-\alpha^2}}\biggr).
\end{eqnarray*}

For $\alpha=1$, we obtain

\begin{eqnarray*}
Q_1(t)&=&\lim_N\frac{1}{\ln N}\sum_{j=1}^N\frac{1}{(1+|j t|^\beta)^{1/\beta}}
=
\lim_N\frac{1}{|t|\ln N}\int_0^N \frac{1}{(1+|st|^\beta)^{1/\beta}}\, \mathrm{d} (st)\\
&=& \lim_N\frac{1}{|t|\ln N}\int_0^{Nt} \frac{1}{1+|v|}\, \mathrm{d} v
=\frac{1}{|t|},
\end{eqnarray*}

which completes the proof for the case where $\rho_\alpha(t)$ belongs
to the Cauchy family.

